    if(!cash||cash<=0){ return {error:"No price for this qty"}; }
    const pbSize=((PB.model_size||{})[pbModel]||"180mm x 80mm x 230mm");
    const pbNums=pbSize.match(/\d+/g)||[180,80,230];
